-- 3. REMINDERS SYNCHRONIZATION (CREATE FOR ALL NEW POLICIES)
SELECT p.id, 'PENDING', 0, 'Pending', NOW()
FROM policies p
LEFT JOIN reminders r ON r.policy_id = p.id
WHERE r.id IS NULL;

-- 4. RESET STALE REMINDERS FOR ACTIVE RENEWAL POLICIES
UPDATE reminders r
JOIN policies p ON r.policy_id = p.id
SET r.reminder_status = 'PENDING', r.last_call_outcome = 'Pending'
WHERE p.expiry_date >= '2026-11-01'
  AND LOWER(r.last_call_outcome) IN ('renewed', 'pending issuance', 'externally renewed');

COMMIT;

